message.content:
Here is a complete, interactive **photorealistic 3D WebGL scene** built with Three.js that recreates your bamboo forest photograph in real-time 3D.

### What’s Recreated in 3D
* **Exact Wide-Angle Upward Composition:** Matches the steep low-angle perspective looking up into the converging bamboo canopy, including the foreground hero stalks on the center-left and right, dense background grove, and the bright sky clearing.
* **Procedural 3D Bamboo Culms:** Custom geometry with authentic tapered internodes, raised 3D nodal ridges, subtle organic curvature, and synchronized procedural PBR textures (albedo, waxy roughness, fibrous bump map, dark nodal creases, and powdery pale Moso bamboo rings).
* **Overhanging Gnarled Tree (Upper Left):** 3D twisting spline branches with fissured bark and backlit vibrant lime-green deciduous foliage silhouetted against the bright sky gap.
* **Photographic Lighting & Atmosphere:** Custom sky dome shader, ACES Filmic tone mapping, soft sky-bleed bloom (`UnrealBloomPass`), backlit canopy leaves, volumetric sunbeams, drifting sunlit pollen motes, and gentle wind sway.
* **Full 360° Exploration:** Includes a forested floor with fallen leaves so you can orbit freely, switch between **Photo Match**, **Eye-Level Walk**, and **Canopy Orbit** camera presets, and adjust wind/lighting live.

---

### How to Run
1. Save the code below as **`bamboo-grove-3d.html`**.
2. Open it in any modern browser (Chrome, Edge, Firefox, Safari). *(Internet connection required only to load Three.js from jsDelivr CDN.)*

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Photorealistic 3D Bamboo Forest</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body {
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #071109;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      color: #e9f3ea;
    }
    #canvas-container {
      width: 100%;
      height: 100%;
      position: relative;
    }
    #hud {
      position: fixed;
      top: 16px;
      left: 16px;
      z-index: 10;
      background: rgba(10, 20, 13, 0.62);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border: 1px solid rgba(170, 220, 175, 0.22);
      border-radius: 14px;
      padding: 14px 16px;
      width: 260px;
      box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
      transition: opacity 0.25s ease;
    }
    #hud h1 {
      font-size: 14px;
      font-weight: 600;
      letter-spacing: 0.4px;
      margin-bottom: 4px;
      color: #d7f5da;
    }
    #hud p {
      font-size: 11px;
      color: rgba(215, 240, 218, 0.72);
      margin-bottom: 12px;
      line-height: 1.4;
    }
    .btn-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 6px;
      margin-bottom: 12px;
    }
    button {
      background: rgba(135, 205, 145, 0.14);
      border: 1px solid rgba(165, 225, 172, 0.28);
      color: #e4f7e6;
      border-radius: 8px;
      padding: 7px 8px;
      font-size: 11px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.18s ease;
    }
    button:hover {
      background: rgba(135, 205, 145, 0.28);
      border-color: rgba(190, 245, 196, 0.55);
    }
    button.active {
      background: rgba(110, 195, 122, 0.38);
      border-color: #a9efb2;
      color: #ffffff;
    }
    .slider-group {
      margin-bottom: 9px;
    }
    .slider-label {
      display: flex;
      justify-content: space-between;
      font-size: 11px;
      color: rgba(225, 245, 228, 0.85);
      margin-bottom: 4px;
    }
    input[type="range"] {
      width: 100%;
      accent-color: #82d98e;
      cursor: pointer;
    }
    #toggle-ui {
      position: fixed;
      top: 16px;
      right: 16px;
      z-index: 11;
      padding: 8px 12px;
      background: rgba(10, 20, 13, 0.62);
      backdrop-filter: blur(10px);
    }
    .hidden {
      opacity: 0;
      pointer-events: none;
    }
  </style>

  <script type="importmap">
  {
    "imports": {
      "three": "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js",
      "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/"
    }
  }
  </script>
</head>
<body>
  <div id="canvas-container"></div>

  <button id="toggle-ui">Hide UI</button>

  <div id="hud">
    <h1>Arashiyama Bamboo Grove 3D</h1>
    <p>Drag to look around &bull; Scroll to zoom &bull; Right-drag to pan</p>

    <div class="btn-row">
      <button id="cam-photo" class="active">Photo Match</button>
      <button id="cam-walk">Eye Level</button>
      <button id="cam-orbit">Canopy Drift</button>
      <button id="cam-wide">Ultra-Wide</button>
    </div>

    <div class="slider-group">
      <div class="slider-label"><span>Wind Sway</span><span id="val-wind">1.0x</span></div>
      <input id="ctrl-wind" type="range" min="0" max="2.5" step="0.1" value="1.0" />
    </div>
    <div class="slider-group">
      <div class="slider-label"><span>Sun Exposure</span><span id="val-exp">1.10</span></div>
      <input id="ctrl-exp" type="range" min="0.7" max="1.6" step="0.02" value="1.10" />
    </div>
    <div class="slider-group">
      <div class="slider-label"><span>Sky Bloom</span><span id="val-bloom">0.42</span></div>
      <input id="ctrl-bloom" type="range" min="0" max="1.0" step="0.02" value="0.42" />
    </div>
  </div>

  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
    import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
    import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
    import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
    import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

    // Deterministic PRNG for consistent photorealistic layout
    function createRng(seed = 4219) {
      let s = seed >>> 0;
      return () => {
        s = (s * 1664525 + 1013904223) >>> 0;
        return s / 4294967296;
      };
    }
    const rand = createRng(7331);
    const randRange = (a, b) => a + rand() * (b - a);

    // =========================================================================
    // 1. RENDERER, SCENE, CAMERA & POST-PROCESSING
    // =========================================================================
    const container = document.getElementById('canvas-container');
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x1b331d, 0.017);

    const camera = new THREE.PerspectiveCamera(
      78,
      window.innerWidth / window.innerHeight,
      0.1,
      220
    );

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: 'high-performance'
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.10;
    container.appendChild(renderer.domElement);

    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.42, // strength
      0.65, // radius
      0.86  // threshold so bright sky gaps bloom softly through foliage
    );
    composer.addPass(bloomPass);
    composer.addPass(new OutputPass());

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.maxDistance = 35;
    controls.minDistance = 0.4;
    controls.maxPolarAngle = Math.PI;

    // Camera presets
    let autoOrbit = false;
    const PRESETS = {
      photo: {
        pos: new THREE.Vector3(0.0, 1.25, 0.0),
        target: new THREE.Vector3(0.45, 15.2, -9.2),
        fov: 78
      },
      walk: {
        pos: new THREE.Vector3(0.0, 1.65, 5.5),
        target: new THREE.Vector3(0.0, 2.4, -8.0),
        fov: 58
      },
      wide: {
        pos: new THREE.Vector3(-0.15, 0.8, 0.4),
        target: new THREE.Vector3(0.4, 16.5, -8.2),
        fov: 92
      }
    };

    function applyPreset(key) {
      autoOrbit = false;
      const p = PRESETS[key];
      camera.position.copy(p.pos);
      controls.target.copy(p.target);
      camera.fov = p.fov;
      camera.updateProjectionMatrix();
      controls.update();
    }
    applyPreset('photo');

    // =========================================================================
    // 2. SKY DOME SHADER & LIGHTING
    // =========================================================================
    const skyGeo = new THREE.SphereGeometry(140, 40, 28);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        uSunDir: { value: new THREE.Vector3(-0.36, 0.90, -0.22).normalize() }
      },
      vertexShader: `
        varying vec3 vWorldPos;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorldPos = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform vec3 uSunDir;
        varying vec3 vWorldPos;
        void main() {
          vec3 dir = normalize(vWorldPos);
          float h = clamp(dir.y, 0.0, 1.0);

          // Overcast-bright luminous zenith matching the photograph's airy sky gaps
          vec3 horizonCol = vec3(0.22, 0.36, 0.24);
          vec3 midSkyCol  = vec3(0.76, 0.89, 0.94);
          vec3 zenithCol  = vec3(1.25, 1.38, 1.42);

          vec3 col = mix(horizonCol, midSkyCol, smoothstep(0.0, 0.35, h));
          col = mix(col, zenithCol, smoothstep(0.28, 0.85, h));

          // Bright solar glow through upper-left clearing
          float sunDot = max(dot(dir, uSunDir), 0.0);
          col += vec3(1.1, 1.15, 1.0) * pow(sunDot, 5.0) * 0.65;
          col += vec3(1.4, 1.42, 1.32) * pow(sunDot, 24.0) * 0.8;

          gl_FragColor = vec4(col, 1.0);
        }
      `
    });
    scene.add(new THREE.Mesh(skyGeo, skyMat));

    // Main overhead sunlight
    const sunLight = new THREE.DirectionalLight(0xf6ffe8, 3.2);
    sunLight.position.set(-14, 42, -8);
    sunLight.castShadow = true;
    sunLight.shadow.mapSize.set(2048, 2048);
    sunLight.shadow.camera.near = 5;
    sunLight.shadow.camera.far = 90;
    const d = 24;
    sunLight.shadow.camera.left = -d;
    sunLight.shadow.camera.right = d;
    sunLight.shadow.camera.top = d;
    sunLight.shadow.camera.bottom = -d;
    sunLight.shadow.bias = -0.0004;
    scene.add(sunLight);

    // Rich forest canopy ambient fill
    const hemiLight = new THREE.HemisphereLight(0xd9f2e6, 0x162b14, 1.45);
    scene.add(hemiLight);

    // Cool subtle rim light from opposite sky gap
    const rimLight = new THREE.DirectionalLight(0xbce8d8, 0.9);
    rimLight.position.set(12, 28, 10);
    scene.add(rimLight);

    // =========================================================================
    // 3. PROCEDURAL PBR TEXTURES (BAMBOO, LEAVES, BARK, FOREST FLOOR)
    // =========================================================================
    function createBambooTextures() {
      const w = 512, h = 1024;

      // Albedo
      const cCol = document.createElement('canvas');
      cCol.width = w; cCol.height = h;
      const ctx = cCol.getContext('2d');

      // Base muted sage/blue-green Moso bamboo gradient
      const bg = ctx.createLinearGradient(0, 0, w, 0);
      bg.addColorStop(0.0, '#4f6e59');
      bg.addColorStop(0.3, '#5d7c65');
      bg.addColorStop(0.65, '#4c6a55');
      bg.addColorStop(1.0, '#4f6e59');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      // Vertical organic internode shading (slight darkening toward upper node)
      const vg = ctx.createLinearGradient(0, 0, 0, h);
      vg.addColorStop(0.0, 'rgba(20, 32, 22, 0.25)');
      vg.addColorStop(0.12, 'rgba(220, 238, 222, 0.16)');
      vg.addColorStop(0.5, 'rgba(0, 0, 0, 0.0)');
      vg.addColorStop(0.92, 'rgba(30, 48, 32, 0.12)');
      vg.addColorStop(1.0, 'rgba(18, 28, 18, 0.30)');
      ctx.fillStyle = vg;
      ctx.fillRect(0, 0, w, h);

      // Fine fibrous vertical striations
      for (let i = 0; i < 1200; i++) {
        const x = rand() * w;
        const lw = randRange(0.5, 2.2);
        const light = rand() > 0.5;
        ctx.fillStyle = light
          ? `rgba(175, 205, 178, ${randRange(0.03, 0.09)})`
          : `rgba(22, 42, 28, ${randRange(0.04, 0.11)})`;
        ctx.fillRect(x, 0, lw, h);
      }

      // Subtle weathering flecks & pale waxy bloom patches
      for (let i = 0; i < 240; i++) {
        const x = rand() * w;
        const y = rand() * h;
        const rx = randRange(4, 24);
        const ry = randRange(10, 60);
        ctx.fillStyle = rand() > 0.45
          ? `rgba(185, 205, 188, ${randRange(0.03, 0.09)})`
          : `rgba(40, 56, 36, ${randRange(0.05, 0.13)})`;
        ctx.beginPath();
        ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // Signature Moso bamboo node details at v=0 / v=1
      // Powdery pale whitish-sage ring right below the node
      const powderGrad = ctx.createLinearGradient(0, 0, 0, 68);
      powderGrad.addColorStop(0.0, 'rgba(205, 220, 208, 0.55)');
      powderGrad.addColorStop(0.45, 'rgba(195, 212, 198, 0.30)');
      powderGrad.addColorStop(1.0, 'rgba(185, 205, 188, 0.0)');
      ctx.fillStyle = powderGrad;
      ctx.fillRect(0, 0, w, 68);

      // Crisp dark brown-black sheath scar & nodal crease
      ctx.fillStyle = 'rgba(24, 28, 20, 0.85)';
      ctx.fillRect(0, 0, w, 10);
      ctx.fillRect(0, h - 12, w, 12);

      ctx.fillStyle = 'rgba(145, 162, 138, 0.45)';
      ctx.fillRect(0, 10, w, 6);
      ctx.fillRect(0, h - 20, w, 6);

      // Bump map
      const cBump = document.createElement('canvas');
      cBump.width = w; cBump.height = h;
      const bctx = cBump.getContext('2d');
      bctx.fillStyle = '#808080';
      bctx.fillRect(0, 0, w, h);
      for (let i = 0; i < 900; i++) {
        const x = rand() * w;
        bctx.fillStyle = rand() > 0.5 ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
        bctx.fillRect(x, 0, randRange(0.6, 2.0), h);
      }
      bctx.fillStyle = '#ffffff';
      bctx.fillRect(0, 10, w, 12);
      bctx.fillRect(0, h - 24, w, 12);
      bctx.fillStyle = '#181818';
      bctx.fillRect(0, 0, w, 9);
      bctx.fillRect(0, h - 10, w, 10);

      // Roughness map (waxy smooth internode, chalkier node ring)
      const cRough = document.createElement('canvas');
      cRough.width = w; cRough.height = h;
      const rctx = cRough.getContext('2d');
      rctx.fillStyle = '#6c6c6c'; // ~0.42 waxy sheen
      rctx.fillRect(0, 0, w, h);
      for (let i = 0; i < 300; i++) {
        rctx.fillStyle = `rgba(210, 210, 210, ${randRange(0.05, 0.16)})`;
        rctx.beginPath();
        rctx.ellipse(rand() * w, rand() * h, randRange(6, 30), randRange(12, 65), 0, 0, Math.PI * 2);
        rctx.fill();
      }
      rctx.fillStyle = '#d0d0d0'; // matte powdery ring
      rctx.fillRect(0, 0, w, 58);
      rctx.fillRect(0, h - 26, w, 26);

      const map = new THREE.CanvasTexture(cCol);
      map.colorSpace = THREE.SRGBColorSpace;
      const bumpMap = new THREE.CanvasTexture(cBump);
      const roughnessMap = new THREE.CanvasTexture(cRough);

      for (const t of [map, bumpMap, roughnessMap]) {
        t.wrapS = THREE.RepeatWrapping;
        t.wrapT = THREE.RepeatWrapping;
        t.anisotropy = 8;
      }
      return { map, bumpMap, roughnessMap };
    }

    function createBambooLeafTexture() {
      const size = 512;
      const c = document.createElement('canvas');
      c.width = size; c.height = size;
      const ctx = c.getContext('2d');
      ctx.clearRect(0, 0, size, size);

      // Slender branching twigs
      ctx.strokeStyle = '#385822';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(size * 0.5, size * 0.95);
      ctx.quadraticCurveTo(size * 0.48, size * 0.52, size * 0.52, size * 0.14);
      ctx.stroke();

      // Cluster of lanceolate bamboo leaves
      function drawLeaf(ox, oy, angle, length, width, shade) {
        ctx.save();
        ctx.translate(ox, oy);
        ctx.rotate(angle);

        const g = ctx.createLinearGradient(0, 0, length, 0);
        g.addColorStop(0.0, `hsl(${92 + shade}, 62%, ${26 + shade * 0.4}%)`);
        g.addColorStop(0.5, `hsl(${88 + shade}, 72%, ${38 + shade * 0.5}%)`);
        g.addColorStop(1.0, `hsl(${78 + shade}, 80%, ${48 + shade * 0.4}%)`);

        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(length * 0.28, -width, length, 0);
        ctx.quadraticCurveTo(length * 0.28, width, 0, 0);
        ctx.fill();

        // Central midrib
        ctx.strokeStyle = 'rgba(215, 245, 130, 0.35)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(2, 0);
        ctx.lineTo(length * 0.92, 0);
        ctx.stroke();

        ctx.restore();
      }

      const nodes = [
        [0.50, 0.82], [0.46, 0.68], [0.54, 0.62],
        [0.44, 0.48], [0.56, 0.44], [0.49, 0.32], [0.52, 0.20]
      ];
      for (const [nx, ny] of nodes) {
        const count = 4 + Math.floor(rand() * 3);
        for (let i = 0; i < count; i++) {
          const ang = -Math.PI * 0.95 + (i / (count - 1)) * Math.PI * 0.9 + randRange(-0.22, 0.22);
          drawLeaf(
            nx * size + randRange(-14, 14),
            ny * size + randRange(-14, 14),
            ang,
            randRange(95, 185),
            randRange(11, 20),
            randRange(-12, 14)
          );
        }
      }

      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      return tex;
    }

    function createTreeLeafTexture() {
      const size = 512;
      const c = document.createElement('canvas');
      c.width = size; c.height = size;
      const ctx = c.getContext('2d');
      ctx.clearRect(0, 0, size, size);

      // Vibrant sunlit yellow-green maple/hardwood foliage for upper-left tree
      for (let i = 0; i < 65; i++) {
        const angle = rand() * Math.PI * 2;
        const dist = Math.pow(rand(), 0.7) * 185;
        const x = size * 0.5 + Math.cos(angle) * dist;
        const y = size * 0.5 + Math.sin(angle) * dist;
        const r = randRange(18, 42);

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(rand() * Math.PI * 2);
        const hue = randRange(72, 102);
        const light = randRange(34, 56);
        ctx.fillStyle = `hsla(${hue}, 82%, ${light}%, 0.94)`;
        ctx.beginPath();
        ctx.ellipse(0, 0, r, r * 0.52, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      return tex;
    }

    function createBarkTexture() {
      const w = 512, h = 512;
      const c = document.createElement('canvas');
      c.width = w; c.height = h;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#1e1b16';
      ctx.fillRect(0, 0, w, h);

      for (let i = 0; i < 700; i++) {
        const x = rand() * w;
        const y = rand() * h;
        ctx.fillStyle = rand() > 0.35
          ? `rgba(12, 10, 8, ${randRange(0.25, 0.75)})`
          : `rgba(68, 74, 48, ${randRange(0.15, 0.45)})`;
        ctx.fillRect(x, y, randRange(2, 9), randRange(20, 110));
      }
      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      tex.repeat.set(2, 6);
      return tex;
    }

    function createFloorTexture() {
      const s = 512;
      const c = document.createElement('canvas');
      c.width = s; c.height = s;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#24291b';
      ctx.fillRect(0, 0, s, s);

      // Damp soil + fallen golden-brown bamboo leaves
      for (let i = 0; i < 1800; i++) {
        ctx.save();
        ctx.translate(rand() * s, rand() * s);
        ctx.rotate(rand() * Math.PI * 2);
        const isMoss = rand() < 0.25;
        ctx.fillStyle = isMoss
          ? `rgba(48, 76, 32, ${randRange(0.2, 0.5)})`
          : `rgba(${Math.floor(randRange(80, 130))}, ${Math.floor(randRange(68, 102))}, ${Math.floor(randRange(38, 56))}, ${randRange(0.25, 0.6)})`;
        ctx.beginPath();
        ctx.ellipse(0, 0, randRange(6, 18), randRange(1.8, 4), 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      tex.repeat.set(22, 22);
      return tex;
    }

    // =========================================================================
    // 4. PROCEDURAL 3D BAMBOO CULM GEOMETRY (WITH 3D NODAL RIDGES)
    // =========================================================================
    function createBambooCulmGeometry({
      height = 30,
      baseRadius = 0.085,
      topRadius = 0.022,
      nodeCount = 46,
      radialSegs = 14,
      bendX = 0.25,
      bendZ = -0.15
    }) {
      // 4 rings per internode so each node gets a crisp physical 3D ridge
      const ringsPerNode = 4;
      const totalRings = nodeCount * ringsPerNode;
      const vertCount = (totalRings + 1) * (radialSegs + 1);

      const positions = new Float32Array(vertCount * 3);
      const uvs = new Float32Array(vertCount * 2);
      const colors = new Float32Array(vertCount * 3);
      const indices = [];

      const localFracs = [0.0, 0.035, 0.5, 0.965];
      const ridgeScales = [1.075, 0.985, 1.0, 1.045];

      let vIdx = 0;
      for (let r = 0; r <= totalRings; r++) {
        const nodeIdx = Math.floor(r / ringsPerNode);
        const sub = r % ringsPerNode;
        const tNode = nodeIdx + (r === totalRings ? 0 : localFracs[sub]);
        // Slightly shorter internodes near the base, longer higher up (authentic botanical growth)
        const normT = tNode / nodeCount;
        const y = height * Math.pow(normT, 1.06);

        const radiusBase = THREE.MathUtils.lerp(baseRadius, topRadius, Math.pow(normT, 0.85));
        const rScale = r === totalRings ? 1.0 : ridgeScales[sub];
        const radius = radiusBase * rScale;

        // Subtle organic curve
        const curveFactor = normT * normT;
        const cx = bendX * curveFactor + Math.sin(normT * Math.PI * 1.5) * 0.06;
        const cz = bendZ * curveFactor + Math.cos(normT * Math.PI) * 0.04;

        // Vertex color gradient: darker earthy moss at bottom, slightly warmer sunlit upper culm
        const baseShade = THREE.MathUtils.smoothstep(y, 0.0, 3.8);
        const topBright = THREE.MathUtils.smoothstep(y, 12.0, height);
        const cr = THREE.MathUtils.lerp(0.45, 0.98, baseShade) + topBright * 0.14;
        const cg = THREE.MathUtils.lerp(0.52, 1.02, baseShade) + topBright * 0.16;
        const cb = THREE.MathUtils.lerp(0.42, 0.96, baseShade) + topBright * 0.06;

        for (let s = 0; s <= radialSegs; s++) {
          const u = s / radialSegs;
          const theta = u * Math.PI * 2;
          const px = cx + Math.cos(theta) * radius;
          const pz = cz + Math.sin(theta) * radius;

          positions[vIdx * 3 + 0] = px;
          positions[vIdx * 3 + 1] = y;
          positions[vIdx * 3 + 2] = pz;

          uvs[vIdx * 2 + 0] = u;
          uvs[vIdx * 2 + 1] = tNode; // Exact 1:1 UV sync with 3D nodal ridges

          colors[vIdx * 3 + 0] = cr;
          colors[vIdx * 3 + 1] = cg;
          colors[vIdx * 3 + 2] = cb;
          vIdx++;
        }
      }

      const stride = radialSegs + 1;
      for (let r = 0; r < totalRings; r++) {
        for (let s = 0; s < radialSegs; s++) {
          const a = r * stride + s;
          const b = a + 1;
          const c = (r + 1) * stride + s;
          const d = c + 1;
          indices.push(a, b, d, a, d, c);
        }
      }

      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
      geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
      geo.setIndex(indices);
      geo.computeVertexNormals();
      return geo;
    }

    // =========================================================================
    // 5. FOREST FLOOR
    // =========================================================================
    const floorGeo = new THREE.PlaneGeometry(110, 110, 48, 48);
    floorGeo.rotateX(-Math.PI / 2);
    const fPos = floorGeo.attributes.position;
