      { x: 0.72,  z: -1.78, r: 0.118, h: 35, leanX: -0.015, leanZ: 0.012, tint: 0xa2ba9c },
      { x: 1.12,  z: -2.18, r: 0.112, h: 34, leanX: -0.020, leanZ: 0.008, tint: 0x8aa892 },
      { x: 0.56,  z: -2.70, r: 0.075, h: 32, leanX: -0.008, leanZ: 0.004, tint: 0x85a38d },

