      { x: 0.12,  z: -4.20, r: 0.058, h: 29, leanX: 0.004, leanZ: -0.005, tint: 0x7c9c82 },
      { x: -0.25, z: -5.10, r: 0.052, h: 28, leanX: 0.010, leanZ: 0.002, tint: 0x76947c },

