      { x: 2.35,  z: -0.55, r: 0.108, h: 32, leanX: -0.065, leanZ: -0.035, tint: 0x88a490 },
      { x: 2.75,  z: -0.20, r: 0.095, h: 31, leanX: -0.078, leanZ: -0.042, tint: 0x7d9886 },
