    // =========================================================================
    // 8. GNARLED OVERHANGING TREE IN UPPER-LEFT CORNER (PHOTO SIGNATURE)
    // =========================================================================
    const gnarledTreeGroup = new THREE.Group();
    scene.add(gnarledTreeGroup);

    const barkMat = new THREE.MeshStandardMaterial({
      map: createBarkTexture(),
      roughness: 0.92,
      metalness: 0.0,
      color: 0x3b352c
    });

    function createTaperedBranch(points, rStart, rEnd, tubularSegs = 28, radialSegs = 9) {
      const curve = new THREE.CatmullRomCurve3(points);
      const frames = curve.computeFrenetFrames(tubularSegs, false);
      const positions = [];
      const uvs = [];
      const indices = [];
      const p = new THREE.Vector3();
      const v = new THREE.Vector3();

      for (let i = 0; i <= tubularSegs; i++) {
        const t = i / tubularSegs;
        curve.getPointAt(t, p);
        const N = frames.normals[i];
        const B = frames.binormals[i];
        const radius = THREE.MathUtils.lerp(rStart, rEnd, Math.pow(t, 0.82)) *
                       (1.0 + Math.sin(t * 18.0) * 0.06);

        for (let j = 0; j <= radialSegs; j++) {
          const theta = (j / radialSegs) * Math.PI * 2;
          const sin = Math.sin(theta);
          const cos = -Math.cos(theta);
          v.x = p.x + radius * (cos * N.x + sin * B.x);
          v.y = p.y + radius * (cos * N.y + sin * B.y);
          v.z = p.z + radius * (cos * N.z + sin * B.z);
          positions.push(v.x, v.y, v.z);
          uvs.push(j / radialSegs, t * 4);
        }
      }

      const stride = radialSegs + 1;
      for (let i = 0; i < tubularSegs; i++) {
        for (let j = 0; j < radialSegs; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }

      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
      geo.setIndex(indices);
      geo.computeVertexNormals();
      const mesh = new THREE.Mesh(geo, barkMat);
      mesh.castShadow = true;
      return mesh;
    }

    // Main gnarled trunk & twisting overhead boughs extending into upper-left frame
    const mainBoughs = [
      // Trunk rising from off-camera left
      {
        pts: [
          new THREE.Vector3(-9.5, -0.5, 4.2),
