    treeLeaves.instanceMatrix.needsUpdate = true;
    treeLeaves.instanceColor.needsUpdate = true;
    gnarledTreeGroup.add(treeLeaves);

    // =========================================================================
    // 9. VOLUMETRIC GOD RAYS & DRIFTING FOREST POLLEN MOTES
    // =========================================================================
    const rayGeo = new THREE.ConeGeometry(7.5, 36, 24, 1, true);
    const rayMat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      uniforms: {
        uTime: { value: 0 }
      },
      vertexShader: `
        varying vec2 vUv;
        varying vec3 vNormalView;
        varying vec3 vViewDir;
        void main() {
          vUv = uv;
          vec4 mvPos = modelViewMatrix * vec4(position, 1.0);
          vNormalView = normalize(normalMatrix * normal);
          vViewDir = normalize(-mvPos.xyz);
          gl_Position = projectionMatrix * mvPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormalView;
        varying vec3 vViewDir;
        void main() {
          float fresnel = pow(abs(dot(vNormalView, vViewDir)), 2.2);
          float vFade = smoothstep(0.0, 0.35, vUv.y) * smoothstep(1.0, 0.15, vUv.y);
          float shimmer = 0.85 + 0.15 * sin(vUv.x * 18.0 + uTime * 0.45);
          float alpha = fresnel * vFade * shimmer * 0.055;
          vec3 col = vec3(0.75, 0.96, 0.68);
          gl_FragColor = vec4(col, alpha);
        }
      `
    });

    const rayConfigs = [
      { pos: [-3.5, 16, -2.0], rot: [0.18, 0.0, -0.26], scale: [0.9, 1.0, 0.9] },
      { pos: [-1.2, 17, -5.5], rot: [0.14, 0.3, -0.22], scale: [1.1, 1.1, 1.1] },
      { pos: [2.2, 18, -7.2],  rot: [0.12, -0.2, -0.24], scale: [0.85, 1.0, 0.85] }
    ];
    rayConfigs.forEach(rc => {
      const m = new THREE.Mesh(rayGeo, rayMat);
