    // =========================================================================
    // 11. ANIMATION LOOP (NATURAL WIND SWAY & ATMOSPHERE)
    // =========================================================================
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      rayMat.uniforms.uTime.value = t;

      // Gentle forest breeze on hero bamboo stalks
      for (const m of heroMeshes) {
        const { baseRotX, baseRotZ, phase, amp } = m.userData;
        const gust = (Math.sin(t * 0.85 + phase) + 0.45 * Math.sin(t * 1.9 + phase * 1.3)) * amp * windStrength;
        m.rotation.z = baseRotZ + gust;
        m.rotation.x = baseRotX + gust * 0.6;
      }

      // Subtle sway on canopy & gnarled overhanging tree
      leafInstanced.rotation.z = Math.sin(t * 0.72) * 0.008 * windStrength;
      leafInstanced.rotation.x = Math.cos(t * 0.55) * 0.006 * windStrength;
      gnarledTreeGroup.rotation.z = Math.sin(t * 0.65 + 1.1) * 0.004 * windStrength;

      // Drift floating pollen motes gently upward and sideways
      const mArr = moteGeo.attributes.position.array;
      for (let i = 0; i < moteCount; i++) {
        const sp = moteSpeeds[i];
        mArr[i * 3 + 0] += Math.sin(t * 0.4 + i) * 0.004 * (0.4 + windStrength);
        mArr[i * 3 + 1] += 0.003 * sp;
        if (mArr[i * 3 + 1] > 25) mArr[i * 3 + 1] = 1.0;
      }
      moteGeo.attributes.position.needsUpdate = true;

      // Optional cinematic drift
      if (autoOrbit) {
        const angle = t * 0.14;
        camera.position.x = Math.sin(angle) * 2.2;
        camera.position.z = Math.cos(angle) * 2.2 - 1.5;
        camera.position.y = 1.4 + Math.sin(t * 0.3) * 0.25;
        controls.target.set(0.3, 15.5, -7.5);
      }

      controls.update();
      composer.render();
    }

    animate();
  </script>
